-- ================= UT2 SPEEDRUN HELPER MOD (begin) =================
-- Generated by Unravel Two Speedrun Helper. Do not edit by hand:
-- key bindings and mode are set in the helper's settings.
-- UT2SH-MARKER mode=__PM_MODE__ version=__PM_VERSION__
local PM_CFG = __PM_CONFIG__;

local PmLog;
local pm_last_key = nil;
local pm_msg = nil;
local pm_msg_time = 0.0;
local pm_fly_logged = false;

-- State lives in the global Lua table so it survives checkpoint resets
local function PmState()
	local g = getfenv(0);
	local s = rawget(g, "PM_STATE");
	if (s == nil) then
		s = { fly = false, fly_speed = 2.0, speed_index = 3, saved = {} };
		rawset(g, "PM_STATE", s);
	end
	return s;
end
local pm_speeds = { 0.25, 0.5, 1.0, 1.5, 2.0, 3.0, 4.0 };
local pm_fly_speeds = { 0.5, 1.0, 2.0, 4.0, 8.0 };

PmLog = function(text)
	pcall(function()
		local f = io.open("practice_log.txt", "a");
		if (f ~= nil) then f:write(text .. "\n"); f:close(); end
	end);
end

local function PmMessage(self, text)
	pm_msg = text;
	pm_msg_time = 2.0;
	PmLog("[Mod] " .. text);
end

local function PmVecStr(v)
	if (v == nil) then return "nil"; end
	return string.format("(%.3f, %.3f, %.3f)", v.x, v.y, v.z);
end

local function PmKeyCode(dik)
	return dik * 65536;
end

local function PmKeyDown(dik)
	local ok, r = pcall(input.IsKeyDown, PmKeyCode(dik));
	return ok and (r == true);
end

local function PmGetKeyName()
	local ok, key = pcall(input.GetKeyPressed);
	if ((not ok) or (key == nil) or (key < 0)) then
		return nil;
	end
	local ok2, name = pcall(input.TranslateKeyboard, key);
	if (ok2 and name ~= nil) then
		name = tostring(name);
		if (string.sub(name, 1, 6) == "CWKEY_") then
			name = string.sub(name, 7);
		end
		return name;
	end
	return nil;
end

local function PmApplySpeed(s)
	local speed = pm_speeds[s.speed_index];
	pcall(game.SetGameSpeed, speed);
	local ok, now = pcall(world.GetGameSpeed);
	if (ok and type(now) == "number" and math.abs(now - speed) > 0.01) then
		pcall(world.SetGameSpeed, speed);
		ok, now = pcall(world.GetGameSpeed);
	end
	return speed, now;
end

local function PmTeleportSelf(self, pos)
	pcall(pike_player.Teleport, self, pos);
	pcall(box2d.SetVelocity, self, Vector3(0.0, 0.0, 0.0));
	pcall(animation.FadeOutAllAnimations, self, 0.0);
	pcall(animation.DisableAnimationAccumulationUntilFadeIn, self);
end

local function PmOther()
	for _, flag in ipairs({ false, true }) do
		local ok, c = pcall(character.GetMainCharacter, flag);
		if (ok and c ~= nil) then
			local oks, sec = pcall(pike_player.IsSecondaryPlayer, c);
			if (oks and sec == true) then return c; end
		end
	end
	return nil;
end

local function PmPos(go)
	local ok, pos = pcall(transform.GetTranslation, go);
	if (ok and pos ~= nil) then return { x = pos.x, y = pos.y, z = pos.z }; end
	return nil;
end

-- called by P1 only: saves both Yarnys
local function PmSavePos(self, s)
	local other = PmOther();
	s.saved = { p1 = PmPos(self), p2 = (other ~= nil) and PmPos(other) or nil };
	PmMessage(self, "Position saved P1=" .. PmVecStr(s.saved.p1) .. " P2=" .. PmVecStr(s.saved.p2));
end

-- multi-frame sequence: undock -> teleport -> yarn reset -> optional checkpoint restart
local function PmStartTeleport(s, p1, p2, restart, label)
	s.seq = { frame = 0, p1 = p1, p2 = p2, restart = restart, label = label };
end

local function PmRunSequence(self, s)
	local q = s.seq;
	if (q == nil) then return; end
	q.frame = q.frame + 1;
	local other = PmOther();
	if (q.frame == 1) then
		local okd1, d1 = pcall(pike_player.IsDocked, self);
		if (okd1 and d1) then pcall(character.ForceUndock, false, true); end
		if (other ~= nil) then
			local okd2, d2 = pcall(pike_player.IsDocked, other);
			if (okd2 and d2) then pcall(character.ForceUndock, true, true); end
		end
		PmLog("[TP] " .. q.label .. ": undock (P1 docked=" .. tostring(okd1 and d1) .. ")");
	elseif (q.frame == 3) then
		local t1 = Vector3(q.p1.x, q.p1.y, q.p1.z + 0.02);
		PmTeleportSelf(self, t1);
		if (other ~= nil) then
			local src = q.p2 or q.p1;
			local t2 = Vector3(src.x, src.y, src.z + 0.04);
			if (q.p2 == nil or (math.abs(src.x - q.p1.x) + math.abs(src.z - q.p1.z)) < 0.01) then
				t2 = Vector3(q.p1.x - 0.12, q.p1.y, q.p1.z + 0.04);
			end
			PmTeleportSelf(other, t2);
		end
		PmLog("[TP] " .. q.label .. ": teleported P1=" .. PmVecStr(PmPos(self)) .. " P2=" .. PmVecStr(other and PmPos(other) or nil));
	elseif (q.frame == 5) then
		local okr, err = pcall(function() m_connecting_yarn:Reset(); end);
		PmLog("[TP] Yarn reset: " .. tostring(okr) .. " " .. tostring(err));
		if (not q.restart) then s.seq = nil; end
	elseif (q.restart and q.frame == 20) then
		PmLog("[TP] Checkpoint restart (reloads the level section cleanly)");
		pcall(game.RestartCheckpoint);
		s.seq = nil;
	end
end

local function PmLoadPos(self, s)
	if (s.saved == nil or s.saved.p1 == nil) then
		PmMessage(self, "No position saved");
		return;
	end
	PmStartTeleport(s, s.saved.p1, s.saved.p2, false, "Load position");
end

