local pm_cs_time = 0.0;


local function PmFindCp(name)
	local ok, go = pcall(FindGameObject, name);
	if ((not ok) or go == nil) then return nil; end
	local oka, alive = pcall(Alive, go);
	if (oka and alive == false) then return nil; end
	local okp, pos = pcall(transform.GetTranslation, go);
	if ((not okp) or pos == nil) then return nil; end
	return go, pos;
end

local function PmCpVariants(id)
	local leaf = string.match(id, "|([^|]+)$") or id;
	return { id, string.sub(id, 2), leaf };
end

local function PmCollectCheckpoints(s)
	local list = {};
	local counts = { 0, 0, 0 };
	for i = 1, #pm_cp_ids do
		local entry = pm_cp_ids[i];
		local vars = PmCpVariants(entry[3]);
		for v = 1, 3 do
			if ((s.cp_variant == nil) or (s.cp_variant == v)) then
				local go, pos = PmFindCp(vars[v]);
				if (go ~= nil) then
					counts[v] = counts[v] + 1;
					table.insert(list, { id = entry[3], name = vars[v], variant = v, level = entry[1], part = entry[2], x = pos.x, z = pos.z });
					break;
				end
			end
		end
	end
	PmLog("[CP] Hits per name variant: full=" .. counts[1] .. " no_pipe=" .. counts[2] .. " leaf_only=" .. counts[3]);
	if (s.cp_variant == nil) then
		for v = 1, 3 do if (counts[v] > 0 and s.cp_variant == nil) then s.cp_variant = v; end end
	end
	-- only entries of the chosen variant, ordered by level part
	local filtered = {};
	for i = 1, #list do if (list[i].variant == s.cp_variant) then table.insert(filtered, list[i]); end end
	-- order: parts ascending, inside a part a nearest-neighbour chain
	local parts = {};
	local part_ids = {};
	for i = 1, #filtered do
		local pt = filtered[i].part;
		if (parts[pt] == nil) then parts[pt] = {}; table.insert(part_ids, pt); end
		table.insert(parts[pt], filtered[i]);
	end
	table.sort(part_ids);
	local ordered = {};
	local last = nil;
	for _, pt in ipairs(part_ids) do
		local pool = parts[pt];
		while (#pool > 0) do
			local pick = 1;
			if (last == nil) then
				for i = 1, #pool do
					if (string.find(pool[i].id, "|Start_CheckPoint_1$") ~= nil) then pick = i; end
				end
			else
				local best = 1e30;
				for i = 1, #pool do
					local d = (pool[i].x - last.x) * (pool[i].x - last.x) + (pool[i].z - last.z) * (pool[i].z - last.z);
					if (d < best) then best = d; pick = i; end
				end
			end
			last = table.remove(pool, pick);
			table.insert(ordered, last);
		end
	end
	filtered = ordered;
	return filtered;
end

local function PmJumpCheckpoint(self, s, dir)
	local list = PmCollectCheckpoints(s);
	local lines = {};
	for i = 1, #list do
		table.insert(lines, string.format("  %2d %s part %d %s (%.2f, %.2f)", i, list[i].level, list[i].part, string.match(list[i].id, "|([^|]+)$") or "?", list[i].x, list[i].z));
	end
	PmLog("[CP] found: " .. tostring(#list) .. " (variant " .. tostring(s.cp_variant) .. ")\n" .. table.concat(lines, "\n"));
	if (#list == 0) then
		PmMessage(self, "No checkpoints found");
		return;
	end
	-- current checkpoint: last jump target, otherwise the nearest one
	local okp, me = pcall(transform.GetTranslation, self);
	local cur = nil;
	if (s.cp_last ~= nil) then
		for i = 1, #list do if (list[i].name == s.cp_last) then cur = i; end end
	end
	if (cur == nil and okp and me ~= nil) then
		local best = 1e30;
		for i = 1, #list do
			local d = (list[i].x - me.x) * (list[i].x - me.x) + (list[i].z - me.z) * (list[i].z - me.z);
			if (d < best) then best = d; cur = i; end
		end
	end
	if (cur == nil) then cur = 1; end
	local nxt = math.max(1, math.min(#list, cur + dir));
	s.cp_last = list[nxt].name;
	local name2 = list[nxt].name .. "|" .. string.sub(string.match(list[nxt].name, "([^|]+)$"), 1, -2) .. "2";
	local _, pos1 = PmFindCp(list[nxt].name);
	local _, pos2 = PmFindCp(name2);
	if (dir < 0 and s.cp_restart ~= false and nxt < cur) then
		-- Backwards: the game never re-activates earlier checkpoints,
		-- so restart the level and jump to the target afterwards.
		s.pending_cp = list[nxt].name;
		pcall(function()
			local f = io.open("practice_pending.txt", "w");
			if (f ~= nil) then f:write(list[nxt].name); f:close(); end
		end);
		PmLog("[CP] Backwards -> level restart, then jump to " .. list[nxt].name);
		pcall(game.RestartLevel);
	else
		PmStartTeleport(s, { x = pos1.x, y = pos1.y, z = pos1.z }, pos2 and { x = pos2.x, y = pos2.y, z = pos2.z } or nil, s.cp_restart ~= false, "Checkpoint " .. list[nxt].name);
	end
	PmMessage(self, "Checkpoint " .. tostring(nxt) .. "/" .. tostring(#list) .. ": " .. (string.match(list[nxt].id, "|([^|]+)$") or "?"));
end


-- Diagnostics: log state changes of both Yarnys (only when something changes)
local pm_diag_last = nil;
local pm_diag_t = 0.0;
local function PmDiagState(self, s, dt)
	pm_diag_t = pm_diag_t + dt;
	local slot = m_secondary_player and "2" or "1";
	local okia, ia = pcall(IsInputActive, self);
	local okc1, c1 = pcall(character.IsControlsActive, false);
	local okc2, c2 = pcall(character.IsControlsActive, true);
	local okst, st = pcall(pike_player.InSceneTransition, self);
	-- remember the input state per player for cutscene detection
	-- is this Yarny's input configuration enabled? (cutscenes disable it via "enable_input_configuration")
	local oken, en = pcall(input.GetEnabled, m_input_hash);
	if ((not oken) or type(en) ~= "boolean") then en = nil; end
	local okeg, eng = pcall(input.GetEnabled);
	if ((not okeg) or type(eng) ~= "boolean") then eng = nil; end
	s["ia" .. slot] = (okia and ia == true) and (en ~= false);
	-- is this Yarny moving physically? (autowalk or airborne)
	s["mv" .. slot] = (m_autowalk_enabled == true) or (m_on_ground == false);
	if (s.diag == nil) then s.diag = false; end
	if (not s.diag) then return; end
	local line = string.format("enabled=%s enabled_global=%s ctrl1=%s ctrl2=%s state=%s input_active=%s autowalk=%s IsInputActive=%s ground=%s scene_trans=%s stoppable=%s",
		tostring(en), tostring(eng), tostring(c1), tostring(c2), tostring(m_state), tostring(m_input_active), tostring(m_autowalk_enabled),
		tostring(ia), tostring(m_on_ground), tostring(st), tostring(m_playonce_stoppable));
	if (line ~= pm_diag_last) then
		pm_diag_last = line;
		PmLog(string.format("[DIAG] P%s t=%.2f %s fast=%s", slot, pm_diag_t, line, tostring(s.cs_fast)));
	end
end

local pm_cs_still = 0.0;
local function PmCutsceneUpdate(self, s, dt)
	if (m_secondary_player) then return; end
	if (not s.cs_skip) then
		if (s.cs_fast) then s.cs_fast = false; PmApplySpeed(s); end
		return;
	end
	local okm, in_menu = pcall(game.IsInMenus);
	local okc, controls = pcall(character.IsControlsActive, false);
	local okc2, controls2 = pcall(character.IsControlsActive, true);
	local none_active = (okc and controls == false) and ((not okc2) or controls2 == false);
	-- additionally: neither Yarny accepts input (autowalk, scripted animation, ...)
	local no_input = (s.ia1 == false) and (s.ia2 == false);
	local in_cs = none_active or no_input or ((m_state == c_state_playonce) and (okc and controls == true));
	if (okm and in_menu) then in_cs = false; end
	if (in_cs) then pm_cs_time = pm_cs_time + dt; else pm_cs_time = 0.0; end
	-- speed: 20x only while no Yarny moves physically;
	-- 5x during autowalk/jump/fall, otherwise they tunnel through the floor.
	if (s.mv1 or s.mv2) then pm_cs_still = 0.0; else pm_cs_still = pm_cs_still + dt; end
	local wanted = PM_CFG.cs_speed_moving or 5.0;
	if (pm_cs_still > 0.5) then wanted = PM_CFG.cs_speed_still or 20.0; end
	if (pm_cs_time > 0.25 and (not s.cs_fast or s.cs_speed ~= wanted)) then
		local first = not s.cs_fast;
		s.cs_fast = true;
		s.cs_speed = wanted;
		pcall(game.SetGameSpeed, wanted);
		local got = tostring(wanted);
		if (first) then
			PmLog("[CS] Cutscene detected -> fast-forward " .. got .. "x (no_input=" .. tostring(no_input) .. ", state=" .. tostring(m_state) .. ", p1=" .. tostring(controls) .. ", p2=" .. tostring(controls2) .. ")");
		else
			PmLog("[CS] Speed adjusted -> " .. got .. "x (moving=" .. tostring(s.mv1) .. "/" .. tostring(s.mv2) .. ")");
		end
	elseif (pm_cs_time == 0.0 and s.cs_fast) then
		s.cs_fast = false;
		s.cs_speed = nil;
		PmApplySpeed(s);
		PmLog("[CS] Cutscene over -> normal speed");
	end
end

local pm_pending_frames = 0;
local pm_pending_checked = false;

local function PmProcessPendingLevelJump(self, s)
	if (not pm_pending_checked) then
		pm_pending_checked = true;
		if (s.pending_cp == nil) then
			pcall(function()
				local f = io.open("practice_pending.txt", "r");
				if (f ~= nil) then
					local t = f:read("*a");
					f:close();
					if (t ~= nil and string.len(t) > 0) then s.pending_cp = t; end
				end
			end);
		end
	end
	if (s.pending_cp == nil) then return; end
	pm_pending_frames = pm_pending_frames + 1;
	if (pm_pending_frames > 3600) then
		PmLog("[CP] Jump after level restart cancelled (timeout)");
		s.pending_cp = nil;
		pcall(os.remove, "practice_pending.txt");
		return;
	end
	if (pm_pending_frames < 90 or s.seq ~= nil) then return; end
	local okc1, c1 = pcall(character.IsControlsActive, false);
	local okc2, c2 = pcall(character.IsControlsActive, true);
	if (not ((okc1 and c1 == true) or (okc2 and c2 == true))) then return; end
	local name = s.pending_cp;
	local _, pos1 = PmFindCp(name);
	if (pos1 == nil) then return; end
	local name2 = name .. "|" .. string.sub(string.match(name, "([^|]+)$"), 1, -2) .. "2";
	local _, pos2 = PmFindCp(name2);
	s.pending_cp = nil;
	pcall(os.remove, "practice_pending.txt");
	PmLog("[CP] Level reloaded -> jumping to " .. name);
	PmStartTeleport(s, { x = pos1.x, y = pos1.y, z = pos1.z }, pos2 and { x = pos2.x, y = pos2.y, z = pos2.z } or nil, true, "Checkpoint " .. name);
end

-- ---------------------------------------------------------------
-- Input: keyboard keys and controller combos are mapped to actions
-- ---------------------------------------------------------------
local pm_bind_map = nil;      -- input name -> action
local pm_pad_buttons = nil;   -- controller action names used in bindings
local pm_last_input = nil;    -- combined input of the previous frame (edge detection)
local pm_held = nil;          -- combined input currently held

local function PmBuildBindMap()
	pm_bind_map = {};
	pm_pad_buttons = {};
	local seen = {};
	for action, list in pairs(PM_CFG.binds or {}) do
		for _, name in ipairs(list) do
			pm_bind_map[name] = action;
			local btn = string.match(name, "^PAD:(.+)$");
			if (btn ~= nil and not seen[btn] and btn ~= "Left" and btn ~= "Right" and btn ~= "Up" and btn ~= "Down") then
				seen[btn] = true;
				table.insert(pm_pad_buttons, btn);
			end
		end
	end
end

local function PmHeldFor(action)
	if (pm_held == nil) then return false; end
	return pm_bind_map[pm_held] == action;
end

-- Controller combo: modifier held + button / stick direction. Read per Yarny with its own input configuration.
local function PmPadName()
	local pad = PM_CFG.pad;
	if (pad == nil or pad.enabled ~= true or pad.modifier == nil) then return nil; end
	if (not m_input_active) then return nil; end
	local okm, mod = pcall(input.GetBool, m_input_hash, CWHASH(pad.modifier));
	if (not (okm and mod == true)) then return nil; end
	for _, btn in ipairs(pm_pad_buttons) do
		local ok, v = pcall(input.GetBool, m_input_hash, CWHASH(btn));
		if (ok and v == true) then return "PAD:" .. btn; end
	end
	local okx, x = pcall(input.GetFloat, m_input_hash, CWHASH("MoveX"));
	local oky, y = pcall(input.GetFloat, m_input_hash, CWHASH("MoveY"));
	if (okx and type(x) == "number") then
		if (x < -0.7) then return "PAD:Left"; end
		if (x > 0.7) then return "PAD:Right"; end
	end
	if (oky and type(y) == "number") then
		if (y < -0.7) then return "PAD:Up"; end
		if (y > 0.7) then return "PAD:Down"; end
	end
	return nil;
end

local function PmDoAction(self, s, action)
	if (action == "fly_toggle") then
		s.fly = not s.fly;
		PmMessage(self, "Fly: " .. tostring(s.fly));
	elseif (action == "fly_slower" or action == "fly_faster") then
		local idx = 1;
		for i = 1, #pm_fly_speeds do
			if (pm_fly_speeds[i] == s.fly_speed) then idx = i; end
		end
		if (action == "fly_faster") then idx = math.min(idx + 1, #pm_fly_speeds); else idx = math.max(idx - 1, 1); end
		s.fly_speed = pm_fly_speeds[idx];
		PmMessage(self, "Fly speed: " .. tostring(s.fly_speed));
	elseif (action == "checkpoint_reload") then
		PmMessage(self, "Reload checkpoint");
		pcall(game.RestartCheckpoint);
	elseif (action == "position_save") then
		PmSavePos(self, s);
	elseif (action == "position_load") then
		PmLoadPos(self, s);
	elseif (action == "checkpoint_prev" or action == "checkpoint_next") then
		PmJumpCheckpoint(self, s, (action == "checkpoint_next") and 1 or -1);
	elseif (action == "checkpoint_restart_toggle") then
		s.cp_restart = (s.cp_restart == false);
		PmMessage(self, "Checkpoint jump with restart: " .. tostring(s.cp_restart));
	elseif (action == "cutscene_toggle") then
		s.cs_skip = not s.cs_skip;
		PmMessage(self, "Cutscene fast-forward: " .. tostring(s.cs_skip));
	elseif (action == "speed_up" or action == "speed_down") then
		if (action == "speed_up") then
			s.speed_index = math.min(s.speed_index + 1, #pm_speeds);
		else
			s.speed_index = math.max(s.speed_index - 1, 1);
		end
		local wanted = PmApplySpeed(s);
		PmMessage(self, "Game speed: " .. tostring(wanted));
	elseif (action == "diag_toggle") then
		s.diag = not s.diag;
		PmMessage(self, "Diagnostic log: " .. tostring(s.diag));
	end
end

local pm_was_flying = false;
local pm_started = false;

-- early in Update: input, sequences, cutscene detection
function PracticeUpdate(self, dt)
	local s = PmState();
	if (pm_bind_map == nil) then PmBuildBindMap(); end
	local slot = m_secondary_player and "2" or "1";
	local speedrun = (PM_CFG.mode == "speedrun");

	if (not pm_started) then
		pm_started = true;
		if (s.cs_skip == nil) then s.cs_skip = (PM_CFG.cutscene_default == true); end
		if (not m_secondary_player) then
			PmLog("[Mod] loaded, mode=" .. tostring(PM_CFG.mode));
		end
	end

	if (speedrun) then
		-- speedrun mode: everything off, cutscene fast-forward always on
		s.cs_skip = true;
		s.fly = false;
		s.diag = false;
	else
		-- controller combos are read by each Yarny with its own input configuration
		local okp, padname = pcall(PmPadName);
		s["pad" .. slot] = (okp and padname) or nil;
		if (not m_secondary_player) then
			local name = PmGetKeyName();
			if (name == nil or pm_bind_map[name] == nil) then
				name = s.pad1 or s.pad2 or name;
			end
			pm_held = name;
			if (name ~= pm_last_input) then
				pm_last_input = name;
				local action = (name ~= nil) and pm_bind_map[name] or nil;
				if (action ~= nil) then
					PmDoAction(self, s, action);
				end
			end
		end
		if (s.fly) then
			m_flying = true;
		end
		if (not m_secondary_player) then
			pcall(PmProcessPendingLevelJump, self, s);
			pcall(PmRunSequence, self, s);
		end
	end
	pcall(PmDiagState, self, s, dt);
	pcall(PmCutsceneUpdate, self, s, dt);
	if (pm_msg ~= nil and pm_msg_time > 0.0 and (not m_secondary_player)) then
		pm_msg_time = pm_msg_time - dt;
		pcall(function()
			debug.AddText(pm_msg, transform.GetTranslation(self) + Vector3(0.0, 0.0, 0.3), 1.5, colors.YELLOW);
		end);
	end
end

-- end of Update: own flight control (overrides the game physics)
function PracticeLateUpdate(self, dt)
	local s = PmState();
	if (not s.fly) then
		if (pm_was_flying) then
			pm_was_flying = false;
			m_flying = false;
			pcall(box2d.SetGravityScale, self, 1.0);
		end
		return;
	end
	pm_was_flying = true;
	local mx = 0.0;
	local my = 0.0;
	if (m_input_active) then
		local ok1, x = pcall(input.GetFloat, m_input_hash, CWHASH("MoveX"));
		local ok2, y = pcall(input.GetFloat, m_input_hash, CWHASH("MoveY"));
		if (ok1 and type(x) == "number") then mx = x; end
		if (ok2 and type(y) == "number") then my = -y; end
		-- up: jump button
		local okj, jump = pcall(input.GetBool, m_input_hash, CWHASH("Jump"));
		if (okj and jump == true) then my = 1.0; end
		local okd, down = pcall(input.GetBool, m_input_hash, CWHASH("MoveYDown"));
		if (okd and down == true) then my = -1.0; end
		-- held keys bound to fly_up / fly_down
		if (PmHeldFor("fly_up")) then my = 1.0; end
		if (PmHeldFor("fly_down")) then my = -1.0; end
	end
	if (math.abs(mx) < 0.2) then mx = 0.0; end
	if (math.abs(my) < 0.2) then my = 0.0; end
	pcall(box2d.SetGravityScale, self, 0.0);
	pcall(box2d.SetVelocity, self, Vector3(mx * s.fly_speed, 0.0, my * s.fly_speed));
end
-- ================= UT2 SPEEDRUN HELPER MOD (end) =================
